import java.util.*;
public class Main {
    static String render(String accept, Map<String,String> m){
        boolean wantJson = accept.contains("application/json");
        StringBuilder sb=new StringBuilder();
        if(wantJson){
            sb.append("{");
            int i=0;
            for(Map.Entry<String,String>e:m.entrySet()){
                if(i++>0)sb.append(",");
                sb.append("\"").append(e.getKey()).append("\":\"").append(e.getValue()).append("\"");
            }
            sb.append("}");
        } else {
            sb.append("<user>");
            for(Map.Entry<String,String>e:m.entrySet())
                sb.append("<").append(e.getKey()).append(">").append(e.getValue()).append("</").append(e.getKey()).append(">");
            sb.append("</user>");
        }
        return (wantJson?"JSON":"XML")+": "+sb;
    }
    public static void main(String[] a){
        Map<String,String> m=new LinkedHashMap<>();
        m.put("id","7"); m.put("name","alice");
        System.out.println(render("application/json",m));
        System.out.println(render("text/html,application/xml",m));
    }
}
